const request = $('When Executed by Another Workflow').first().json;

const userId = String(request.user_id || '').trim();
const query = String(request.search_query || '')
  .toLowerCase()
  .trim();

if (!userId || !query) {
  return [{
    json: {
      success: false,
      memories: [],
      count: 0,
      message: 'Missing user ID or search query'
    }
  }];
}

// Parse DD MM YYYY HH:mm (Pakistan time) for sorting
function parseDate(value) {
  const match = String(value || '').match(
    /^(\d{2}) (\d{2}) (\d{4})(?: (\d{2}):(\d{2}))?$/
  );

  if (!match) return 0;

  const [, day, month, year, hour = '00', minute = '00'] = match;

  return Date.UTC(
    Number(year),
    Number(month) - 1,
    Number(day),
    Number(hour),
    Number(minute)
  );
}

// Only retrieve the current user's records
const rows = $input.all()
  .map(item => item.json)
  .filter(row => String(row.user_id || '').trim() === userId);

// Keep the latest record for each memory subject
const latest = new Map();

for (const row of rows) {
  const key = String(
    row.lookup_key ||
    `${userId}:${row.memory_key || row.memory_id}`
  );

  const existing = latest.get(key);

  if (
    !existing ||
    parseDate(row.updated_at) > parseDate(existing.updated_at)
  ) {
    latest.set(key, row);
  }
}

// Extract keywords
const words = [...new Set(
  query.split(/[^a-z0-9]+/)
    .filter(word => word.length > 2)
)];

// Score memories
const matches = [...latest.values()]
  .map(row => {
    const searchable = [
      row.memory_key,
      row.memory_type,
      row.memory_text
    ].join(' ').toLowerCase().replace(/_/g, ' ');

    const score = words.reduce(
      (total, word) =>
        total + (searchable.includes(word) ? 1 : 0),
      0
    );

    return { row, score };
  })
  .filter(item => item.score > 0)
  .sort((a, b) =>
    b.score - a.score ||
    parseDate(b.row.updated_at) - parseDate(a.row.updated_at)
  )
  .slice(0, 5)
  .map(item => ({
    memory_id: item.row.memory_id,
    memory_key: item.row.memory_key,
    memory_type: item.row.memory_type,
    memory_text: item.row.memory_text,
    updated_at: item.row.updated_at
  }));

return [{
  json: {
    success: true,
    memories: matches,
    count: matches.length,
    message: matches.length
      ? 'Relevant memories found'
      : 'No relevant memories found'
  }
}];
